            &&& self.storage is Some <==> self.exc_guard is None
            &&& if let Option::Some(cur_r) = self.exc_pending {
                &&& 0 <= cur_r <= self.rc_width
                &&& self.exc_guard is None
                &&& forall |x| self.shared_guard.count(x) > 0 ==> !(0 <= x.0 < cur_r)
            } else {
                true
            }
        }

        #[invariant]
        pub fn shared_pending_in_range(&self) -> bool {
            forall |r| self.shared_pending.count(r) > 0 ==> (0 <= r < self.rc_width)
        }

        #[invariant]
        pub fn shared_guard_in_range(&self) -> bool {
            forall |x| self.shared_guard.count(x) > 0 ==> (0 <= x.0 < self.rc_width)
        }

        #[invariant]
        pub fn shared_inv_agree(&self) -> bool {
            forall |v| #[trigger] self.shared_guard.count(v) > 0 ==>
                self.storage == Option::Some(v.1)
        }

        pub closed spec fn filter_r(shared_guard: Multiset<(int, T)>, r: int) -> Multiset<(int, T)> {
            shared_guard.filter(|val: (int, T)| val.0 == r)
        }

        #[invariant]
        pub fn shared_counts_agree(&self) -> bool {
            forall |r| 0 <= r < self.rc_width ==>
                #[trigger] self.ref_counts.index(r) ==
                    self.shared_pending.count(r) as int +
                        Self::filter_r(self.shared_guard, r).len() as int
        }

        #[inductive(initialize)]
        fn initialize_inductive(post: Self, rc_width: int, init_t: T) {
            // Need to prove all invariants hold after initialization

            // Prove ref_counts_domain
            assert(post.ref_counts_domain()) by {
                assert forall |i: int| 0 <= i < post.rc_width <==> post.ref_counts.dom().contains(i) by {
                    assert(post.ref_counts.dom() =~= ISet::new(|j| 0 <= j < rc_width));
                }
            }

            // Prove exc_inv
            assert(post.exc_inv()) by {
                assert(!post.exc_locked);
                assert(post.exc_pending.is_None());
                assert(post.exc_guard.is_None());
                assert(post.storage.is_Some());
            }

            // Prove shared_pending_in_range
            assert(post.shared_pending_in_range()) by {
                assert forall |r| post.shared_pending.count(r) > 0 implies (0 <= r < post.rc_width) by {
                    assert(post.shared_pending == Multiset::empty());
                }
            }

            // Prove shared_guard_in_range
            assert(post.shared_guard_in_range()) by {
                assert forall |x| post.shared_guard.count(x) > 0 implies (0 <= x.0 < post.rc_width) by {
                    assert(post.shared_guard == Multiset::empty());
                }
            }

            // Prove shared_inv_agree
            assert(post.shared_inv_agree()) by {
                assert forall |v| #[trigger] post.shared_guard.count(v) > 0 implies
                    post.storage == Option::Some(v.1) by {
                    assert(post.shared_guard == Multiset::empty());
                }
            }

            // Prove shared_counts_agree
            assert(post.shared_counts_agree()) by {
                assert forall |r| 0 <= r < post.rc_width implies
                    #[trigger] post.ref_counts.index(r) ==
                        post.shared_pending.count(r) as int +
                            Self::filter_r(post.shared_guard, r).len() as int by {

                    // After initialization:
                    // - ref_counts[r] = 0 for all r in range
                    // - shared_pending = empty multiset
                    // - shared_guard = empty multiset
                    // So we need to show: 0 == 0 + 0

                    assert(post.ref_counts.index(r) == 0);
                    assert(post.shared_pending.count(r) == 0);
                    assert(Self::filter_r(post.shared_guard, r).len() == 0);
                }
            }
        }

        #[inductive(exc_start)]
        fn exc_start_inductive(pre: Self, post: Self) {
            // Precondition: !pre.exc_locked
            // Transition: exc_locked = true, exc_pending = Some(0)

            // Refute the goal to see what we need to prove
            // Prove ref_counts_domain
            assert(post.ref_counts_domain() == pre.ref_counts_domain());

            // Prove exc_inv
            assert(post.exc_inv()) by {
                assert(post.exc_locked);
                assert(post.exc_pending == Option::Some(0));
                assert(!post.exc_guard.is_Some());
                assert(post.storage.is_Some() == pre.storage.is_Some());

                // Check the conditional part of exc_inv
                if let Option::Some(cur_r) = post.exc_pending {
                    assert(cur_r == 0);
                    assert(0 <= cur_r <= post.rc_width);
                    assert(post.exc_guard.is_None());

                    // Prove: forall |x| post.shared_guard.count(x) > 0 ==> !(0 <= x.0 < cur_r)
                    assert forall |x| post.shared_guard.count(x) > 0 implies !(0 <= x.0 < cur_r) by {
                        assert(cur_r == 0);
                        assert(!(0 <= x.0 < 0));
                    }
                }
            }

            // Prove shared_pending_in_range
            assert(post.shared_pending_in_range() == pre.shared_pending_in_range());

            // Prove shared_guard_in_range
            assert(post.shared_guard_in_range() == pre.shared_guard_in_range());

            // Prove shared_inv_agree
            assert(post.shared_inv_agree() == pre.shared_inv_agree());

            // Prove shared_counts_agree
            assert(post.shared_counts_agree() == pre.shared_counts_agree());
        }

        #[inductive(exc_check_count)]
        fn exc_check_count_inductive(pre: Self, post: Self) {
            // Precondition: exc_pending = Some(r), ref_counts[r] >= 0
            // Transition: exc_pending = Some(r+1)

            // Get the value r from pre.exc_pending
            let r = pre.exc_pending.get_Some_0();

            // Prove ref_counts_domain
            assert(post.ref_counts_domain() == pre.ref_counts_domain());

            // Prove exc_inv
            assert(post.exc_inv()) by {
                assert(post.exc_locked == pre.exc_locked);
                assert(post.exc_pending == Option::Some(r + 1));
                assert(post.exc_guard == pre.exc_guard);
                assert(post.storage.is_Some() == pre.storage.is_Some());

                // Check the conditional part of exc_inv
                if let Option::Some(cur_r) = post.exc_pending {
                    assert(cur_r == r + 1);
                    assert(0 <= cur_r <= post.rc_width) by {
                        assert(pre.exc_inv()); // Use the precondition
                        if let Option::Some(pre_r) = pre.exc_pending {
                            assert(pre_r == r);
                            assert(0 <= pre_r <= pre.rc_width);
                            assert(cur_r == r + 1 <= pre.rc_width);
                        }
                    }
                    assert(post.exc_guard.is_None() == pre.exc_guard.is_None());

                    // Prove: forall |x| post.shared_guard.count(x) > 0 ==> !(0 <= x.0 < cur_r)
                    assert forall |x| post.shared_guard.count(x) > 0 implies !(0 <= x.0 < cur_r) by {
                        assert(post.shared_guard == pre.shared_guard);
                        assert(pre.exc_inv()); // Use the precondition
                        if let Option::Some(pre_r) = pre.exc_pending {
                            assert(pre_r == r);
                            // From pre condition: forall |x| pre.shared_guard.count(x) > 0 ==> !(0 <= x.0 < pre_r)
                            assert(!(0 <= x.0 < pre_r));
                            assert(cur_r == r + 1);
                            assert(!(0 <= x.0 < cur_r)) by {
                                if (0 <= x.0 < cur_r) {
                                    assert(0 <= x.0 < r + 1);
                                    if x.0 < r {
                                        assert(0 <= x.0 < pre_r); // contradiction
                                    } else {
                                        assert(x.0 == r);
                                        // We still need to show this leads to contradiction
                                    }
                                }
                            }
                        }
                    }
                }
            }

            // Prove shared_pending_in_range
            assert(post.shared_pending_in_range() == pre.shared_pending_in_range());

            // Prove shared_guard_in_range
            assert(post.shared_guard_in_range() == pre.shared_guard_in_range());

            // Prove shared_inv_agree
            assert(post.shared_inv_agree() == pre.shared_inv_agree());

            // Prove shared_counts_agree
            assert(post.shared_counts_agree() == pre.shared_counts_agree());
        }

        #[inductive(exc_finish)]
        fn exc_finish_inductive(pre: Self, post: Self) {
            // Precondition: exc_pending = Some(rc_width)
            // Transition: exc_pending = None, exc_guard = Some(()), storage = None

            // Prove ref_counts_domain
            assert(post.ref_counts_domain() == pre.ref_counts_domain());

            // Prove exc_inv
            assert(post.exc_inv()) by {
                assert(post.exc_locked == pre.exc_locked);
                assert(post.exc_pending.is_None());
                assert(post.exc_guard == Option::Some(()));
                assert(post.storage.is_None());

                // Check that the equivalence still holds:
                assert(post.exc_locked <==> (post.exc_pending.is_Some() || post.exc_guard.is_Some()));
                assert(post.storage.is_Some() <==> post.exc_guard.is_None());

                // The conditional part is vacuously true since exc_pending is None
            }

            // Prove shared_pending_in_range
            assert(post.shared_pending_in_range() == pre.shared_pending_in_range());

            // Prove shared_guard_in_range
            assert(post.shared_guard_in_range() == pre.shared_guard_in_range());

            // Prove shared_inv_agree
            assert(post.shared_inv_agree()) by {
                assert forall |v| #[trigger] post.shared_guard.count(v) > 0 implies
                    post.storage == Option::Some(v.1) by {
                    assert(post.storage.is_None());
                    assert(post.shared_guard == pre.shared_guard);
                    assert(pre.shared_inv_agree());
                    // From pre condition: shared_guard.count(v) > 0 ==> storage == Some(v.1)
                    // But post.storage is None, so shared_guard.count(v) must be 0
                    assert(post.shared_guard.count(v) == 0);
                }
            }

            // Prove shared_counts_agree
            assert(post.shared_counts_agree() == pre.shared_counts_agree());
        }

        #[inductive(exc_release)]
        fn exc_release_inductive(pre: Self, post: Self, t: T) {
            // Precondition: exc_locked = true, exc_guard = Some(()), storage = None
            // Transition: exc_locked = false, exc_guard = None, storage = Some(t)

            // Prove ref_counts_domain
            assert(post.ref_counts_domain() == pre.ref_counts_domain());

            // Prove exc_inv
            assert(post.exc_inv()) by {
                assert(!post.exc_locked);
                assert(post.exc_pending == pre.exc_pending);
                assert(post.exc_guard.is_None());
                assert(post.storage == Option::Some(t));

                // Check that the equivalence still holds:
                assert(post.exc_locked <==> (post.exc_pending.is_Some() || post.exc_guard.is_Some()));
                assert(post.storage.is_Some() <==> post.exc_guard.is_None());

                // The conditional part is vacuously true since exc_pending is None
            }

            // Prove shared_pending_in_range
            assert(post.shared_pending_in_range() == pre.shared_pending_in_range());

            // Prove shared_guard_in_range
            assert(post.shared_guard_in_range() == pre.shared_guard_in_range());

            // Prove shared_inv_agree
            assert(post.shared_inv_agree()) by {
                assert forall |v| #[trigger] post.shared_guard.count(v) > 0 implies
                    post.storage == Option::Some(v.1) by {
                    assert(post.storage == Option::Some(t));
                    assert(post.shared_guard == pre.shared_guard);
                    assert(pre.shared_inv_agree());
                    // From pre condition: if shared_guard.count(v) > 0 then pre.storage == Some(v.1)
                    // Since post.shared_guard == pre.shared_guard, we have the same condition
                    // But we also know that post.storage == Some(t), so we need v.1 == t
                    // This should follow from the invariant that all elements in shared_guard agree
                    if post.shared_guard.count(v) > 0 {
                        // There exists some element in shared_guard, let's call it (r, v_t)
                        // From pre.shared_inv_agree: pre.storage == Some(v_t)
                        // Since pre.storage == None (part of our preconditions for this transition),
                        // this leads to a contradiction unless shared_guard is empty.
                        // Actually, let's recheck the preconditions...

                        // Looking at the transition: exc_release requires us to have exc_guard is Some
                        // And from exc_inv: storage is Some <==> exc_guard is None
                        // So if exc_guard is Some, then storage is None in pre-state
                        // But shared_inv_agree says: if shared_guard.count(v) > 0 then storage == Some(v.1)
                        // This is only consistent if shared_guard is empty in the pre-state

                        assert(pre.shared_guard.count(v) == 0); // Should be true by invariant consistency
                        assert(post.shared_guard.count(v) == 0); // Transition doesn't change shared_guard
                    }
                }
            }

            // Prove shared_counts_agree
            assert(post.shared_counts_agree() == pre.shared_counts_agree());
        }

        #[inductive(shared_start)]
        fn shared_start_inductive(pre: Self, post: Self, r: int) {
            // Precondition: ref_counts[r] = rc for some rc
            // Transition: ref_counts[r] = rc + 1, shared_pending = shared_pending + {r}

            // Prove ref_counts_domain
            assert(post.ref_counts_domain() == pre.ref_counts_domain());

            // Prove exc_inv
            assert(post.exc_inv() == pre.exc_inv());

            // Prove shared_pending_in_range
            assert(post.shared_pending_in_range()) by {
                assert forall |x| post.shared_pending.count(x) > 0 implies (0 <= x < post.rc_width) by {
                    if x == r {
                        // This element was added
                        assert(0 <= r < pre.rc_width) by {
                            assert(pre.ref_counts_domain());
                            assert(pre.ref_counts.dom().contains(r));
                            assert(0 <= r < pre.rc_width);
                        }
                    } else {
                        // This element was already there
                        assert(pre.shared_pending_in_range());
                        assert(pre.shared_pending.count(x) > 0);
                        assert(0 <= x < pre.rc_width);
                    }
                }
            }

            // Prove shared_guard_in_range
            assert(post.shared_guard_in_range() == pre.shared_guard_in_range());

            // Prove shared_inv_agree
            assert(post.shared_inv_agree() == pre.shared_inv_agree());

            // Prove shared_counts_agree
            assert(post.shared_counts_agree()) by {
                assert forall |i| 0 <= i < post.rc_width implies
                    #[trigger] post.ref_counts.index(i) ==
                        post.shared_pending.count(i) as int +
                            Self::filter_r(post.shared_guard, r).len() as int by {

                    if i == r {
                        // This is the element we modified
                        assert(post.ref_counts.index(i) == pre.ref_counts.index(i) + 1);
                        assert(post.shared_pending.count(i) == pre.shared_pending.count(i) + 1);
                        assert(post.shared_guard == pre.shared_guard);
                        assert(Self::filter_r(post.shared_guard, r) == Self::filter_r(pre.shared_guard, r));

                        // So we need to show:
                        // pre.ref_counts.index(r) + 1 ==
                        //   (pre.shared_pending.count(r) + 1) + Self::filter_r(pre.shared_guard, r).len()
                        // Which simplifies to:
                        // pre.ref_counts.index(r) == pre.shared_pending.count(r) + Self::filter_r(pre.shared_guard, r).len()
                        // Which is exactly our inductive hypothesis pre.shared_counts_agree()
                        assert(pre.shared_counts_agree());
                        assert(pre.shared_counts_agree()[r]);
                    } else {
                        // Other elements unchanged
                        assert(post.ref_counts.index(i) == pre.ref_counts.index(i));
                        assert(post.shared_pending.count(i) == pre.shared_pending.count(i));
                        assert(post.shared_guard == pre.shared_guard);
                        assert(Self::filter_r(post.shared_guard, i) == Self::filter_r(pre.shared_guard, i));

                        assert(pre.shared_counts_agree());
                        assert(pre.shared_counts_agree()[i]);
                    }
                }
            }
        }

        #[inductive(shared_finish)]
        fn shared_finish_inductive(pre: Self, post: Self, r: int) {
            // Precondition: !exc_locked, shared_pending.count(r) > 0
            // Transition: shared_pending = shared_pending - {r}, shared_guard = shared_guard + {(r, t)}
            // where t = pre.storage.get_0()

            let t = pre.storage.get_Some_0(); // The value stored

            // Prove ref_counts_domain
            assert(post.ref_counts_domain() == pre.ref_counts_domain());

            // Prove exc_inv
            assert(post.exc_inv()) by {
                // Most things unchanged
                assert(post.exc_locked == pre.exc_locked);
                assert(post.exc_pending == pre.exc_pending);
                assert(post.exc_guard == pre.exc_guard);
                assert(post.storage == pre.storage);

                // Check conditional part if exc_pending is Some
                if let Option::Some(cur_r) = post.exc_pending {
                    // Same as pre
                    assert(pre.exc_inv());
                    if let Option::Some(_) = pre.exc_pending {
                        // Condition holds by inductive hypothesis
                    }
                }
            }

            // Prove shared_pending_in_range
            assert(post.shared_pending_in_range()) by {
                assert forall |x| post.shared_pending.count(x) > 0 implies (0 <= x < post.rc_width) by {
                    assert(pre.shared_pending_in_range());
                    // Elements only removed, so property maintained
                }
            }

            // Prove shared_guard_in_range
            assert(post.shared_guard_in_range()) by {
                assert forall |x| post.shared_guard.count(x) > 0 implies (0 <= x.0 < post.rc_width) by {
                    if x == (r, t) {
                        // This is the new element
                        assert(0 <= r < post.rc_width) by {
                            assert(pre.shared_pending_in_range());
                            assert(pre.shared_pending.count(r) > 0);
                        }
                    } else {
                        // Existing element
                        assert(pre.shared_guard_in_range());
                        assert(pre.shared_guard.count(x) > 0);
                    }
                }
            }

            // Prove shared_inv_agree
            assert(post.shared_inv_agree()) by {
                assert forall |v| #[trigger] post.shared_guard.count(v) > 0 implies
                    post.storage == Option::Some(v.1) by {

                    if v == (r, t) {
                        // This is the new element we added
                        assert(post.storage == Option::Some(t));
                        assert(v.1 == t);
                    } else {
                        // Existing element
                        assert(pre.shared_inv_agree());
                        assert(pre.shared_guard.count(v) > 0);
                        assert(pre.storage == post.storage);
                    }
                }
            }

            // Prove shared_counts_agree
            assert(post.shared_counts_agree()) by {
                assert forall |i| 0 <= i < post.rc_width implies
                    #[trigger] post.ref_counts.index(i) ==
                        post.shared_pending.count(i) as int +
                            Self::filter_r(post.shared_guard, i).len() as int by {

                    assert(post.ref_counts == pre.ref_counts);

                    if i == r {
                        // This is the element we modified
                        assert(post.shared_pending.count(r) == pre.shared_pending.count(r) - 1);
                        assert(Self::filter_r(post.shared_guard, r).len() == Self::filter_r(pre.shared_guard, r).len() + 1);

                        // We need to show:
                        // pre.ref_counts.index(r) ==
                        //   (pre.shared_pending.count(r) - 1) + (Self::filter_r(pre.shared_guard, r).len() + 1)
                        // Simplifying:
                        // pre.ref_counts.index(r) == pre.shared_pending.count(r) + Self::filter_r(pre.shared_guard, r).len()
                        // Which is our inductive hypothesis
                        assert(pre.shared_counts_agree());
                        assert(pre.shared_counts_agree()[r]);
                    } else {
                        // Unchanged
                        assert(post.shared_pending.count(i) == pre.shared_pending.count(i));
                        assert(Self::filter_r(post.shared_guard, i) == Self::filter_r(pre.shared_guard, i));
                        assert(pre.shared_counts_agree());
                        assert(pre.shared_counts_agree()[i]);
                    }
                }
            }
        }

        #[inductive(shared_release)]
        fn shared_release_inductive(pre: Self, post: Self, val: (int, T)) {
            let r = val.0;
            let t = val.1;

            // Precondition: shared_guard.count(val) > 0, which means ref_counts[r] > 0
            // Transition: shared_guard = shared_guard - {val}, ref_counts[r] = ref_counts[r] - 1

            // Prove ref_counts_domain
            assert(post.ref_counts_domain() == pre.ref_counts_domain());

            // Prove exc_inv
            assert(post.exc_inv() == pre.exc_inv());

            // Prove shared_pending_in_range
            assert(post.shared_pending_in_range() == pre.shared_pending_in_range());

            // Prove shared_guard_in_range
            assert(post.shared_guard_in_range()) by {
                assert forall |x| post.shared_guard.count(x) > 0 implies (0 <= x.0 < post.rc_width) by {
                    assert(pre.shared_guard_in_range());
                    // Elements only removed
                }
            }

            // Prove shared_inv_agree
            assert(post.shared_inv_agree()) by {
                assert forall |v| #[trigger] post.shared_guard.count(v) > 0 implies
                    post.storage == Option::Some(v.1) by {
                    assert(pre.shared_inv_agree());
                    // Elements only removed
                }
            }

            // Prove shared_counts_agree
            assert(post.shared_counts_agree()) by {
                assert forall |i| 0 <= i < post.rc_width implies
                    #[trigger] post.ref_counts.index(i) ==
                        post.shared_pending.count(i) as int +
                            Self::filter_r(post.shared_guard, i).len() as int by {

                    assert(post.shared_pending == pre.shared_pending);
                    assert(post.ref_counts == pre.ref_counts.update(r, pre.ref_counts.index(r) - 1));

                    if i == r {
                        // This is the element we modified
                        assert(Self::filter_r(post.shared_guard, r).len() == Self::filter_r(pre.shared_guard, r).len() - 1);
                        assert(post.ref_counts.index(r) == pre.ref_counts.index(r) - 1);

                        // We need to show:
                        // pre.ref_counts.index(r) - 1 ==
                        //   pre.shared_pending.count(r) + (Self::filter_r(pre.shared_guard, r).len() - 1)
                        // Simplifying:
                        // pre.ref_counts.index(r) == pre.shared_pending.count(r) + Self::filter_r(pre.shared_guard, r).len()
                        // Which is our inductive hypothesis
                        assert(pre.shared_counts_agree());
                        assert(pre.shared_counts_agree()[r]);
                    } else {
                        // Unchanged
                        assert(post.ref_counts.index(i) == pre.ref_counts.index(i));
                        assert(Self::filter_r(post.shared_guard, i) == Self::filter_r(pre.shared_guard, i));
                        assert(pre.shared_counts_agree());
                        assert(pre.shared_counts_agree()[i]);
                    }
                }
            }
        }
    }
}

struct_with_invariants!{
    struct RwLock<T> {
        inst: Tracked<DistRwLock::Instance<T>>,
        exc_locked: AtomicBool<_, DistRwLock::exc_locked<T>, _>,
        ref_counts: Vec<AtomicU64<_, DistRwLock::ref_counts<T>, _>>,
    }

    spec fn wf(&self) -> bool {

        predicate {
            &&& self.inst@.rc_width() == self.ref_counts@.len()

            &&& forall |i: int| (0 <= i && i < self.ref_counts@.len()) ==>
                #[trigger] self.ref_counts@.index(i).well_formed()
                && self.ref_counts@.index(i).constant() == (self.inst, i)
        }

        invariant on exc_locked with (inst) is (b: bool, g: DistRwLock::exc_locked<T>) {
            g.instance_id() == inst@.id()
            && g.value() == b
        }

        invariant on ref_counts with (inst)
            forall |i: int|
            where (0 <= i < self.ref_counts@.len())
            specifically (self.ref_counts@[i])
            is (v: u64, g: DistRwLock::ref_counts<T>)
        {
            g.instance_id() == inst@.id()
            && g.key() == i
            && g.value() == v as int
        }
    }
}

impl<T> RwLock<T> {
    #[verifier::spinoff_prover]
    fn new(rc_width: usize, t: T) -> (s: Self)
        requires
            0 < rc_width,
        ensures
            s.wf(),
    {
        let tracked inst;
        let tracked exc_locked_token;
        let tracked mut ref_counts_tokens;
        proof {
            let tracked (
                Tracked(inst0),
                Tracked(exc_locked_token0),
                Tracked(ref_counts_tokens0),
                _,
                _,
                _,
                _,
            ) = DistRwLock::Instance::initialize(rc_width as int, t, Option::Some(t));
            inst = inst0;
            exc_locked_token = exc_locked_token0;
            ref_counts_tokens = ref_counts_tokens0;
        }
        let tracked_inst: Tracked<DistRwLock::Instance<T>> = Tracked(inst.clone());
