        #[inductive(exc_finish)]
        fn exc_finish_inductive(pre: Self, post: Self) {
            // Precondition: exc_pending = Some(rc_width)
            // Transition: exc_pending = None, exc_guard = Some(()), storage = None

            // Assume all pre invariants hold
            assume(pre.ref_counts_domain());
            assume(pre.exc_inv());
            assume(pre.shared_pending_in_range());
            assume(pre.shared_guard_in_range());
            assume(pre.shared_inv_agree());
            assume(pre.shared_counts_agree());

            // Most invariants preserved
            assert(post.ref_counts_domain());
            assert(post.shared_pending_in_range());
            assert(post.shared_guard_in_range());
            assert(post.shared_counts_agree());

            // Prove exc_inv
