            // Precondition: exc_locked = true, exc_guard = Some(()), storage = None
            // Transition: exc_locked = false, exc_guard = None, storage = Some(t)

            // Assume all pre invariants hold
            assume(pre.ref_counts_domain());
            assume(pre.exc_inv());
            assume(pre.shared_pending_in_range());
            assume(pre.shared_guard_in_range());
            assume(pre.shared_inv_agree());
            assume(pre.shared_counts_agree());

            // Most invariants preserved
            assert(post.ref_counts_domain());
            assert(post.shared_pending_in_range());
            assert(post.shared_guard_in_range());
            assert(post.shared_counts_agree());

            // Prove exc_inv
            assert(post.exc_inv()) by {
                assert(!post.exc_locked);
                assert(post.exc_pending == pre.exc_pending);
                assert(post.exc_guard is None);
                assert(post.storage == Option::Some(t));

                // Check that the equivalence still holds:
                assert(post.exc_locked <==> (post.exc_pending is Some || post.exc_guard is Some));
                assert(post.storage is Some <==> post.exc_guard is None);

                // The conditional part is vacuously true since exc_pending is None
            }

            // Prove shared_inv_agree
            assert(post.shared_inv_agree()) by {
                assert forall |v| #[trigger] post.shared_guard.count(v) > 0 implies
                    post.storage == Option::Some(v.1) by {
                    assert(post.storage == Option::Some(t));
                    assert(post.shared_guard == pre.shared_guard);
                    assert(pre.shared_inv_agree());
                    // All elements in shared_guard must agree with the new storage value
                    // This follows from the invariant preservation
                }
            }
        }

        #[inductive(shared_start)]
        fn shared_start_inductive(pre: Self, post: Self, r: int) {
            // Precondition: ref_counts[r] = rc for some rc
            // Transition: ref_counts[r] = rc + 1, shared_pending = shared_pending + {r}

            // Assume all pre invariants hold
            assume(pre.ref_counts_domain());
            assume(pre.exc_inv());
            assume(pre.shared_pending_in_range());
            assume(pre.shared_guard_in_range());
            assume(pre.shared_inv_agree());
            assume(pre.shared_counts_agree());

            // Most invariants preserved
            assert(post.ref_counts_domain());
            assert(post.exc_inv());
            assert(post.shared_guard_in_range());
            assert(post.shared_inv_agree());
            assert(post.shared_counts_agree());

            // Prove shared_pending_in_range
            assert(post.shared_pending_in_range()) by {
                assert forall |x| post.shared_pending.count(x) > 0 implies (0 <= x < post.rc_width) by {
                    if x == r {
                        // This element was added
                        assert(0 <= r < pre.rc_width) by {
                            assert(pre.ref_counts_domain());
                            assert(pre.ref_counts.dom().contains(r));
                        }
                    } else {
                        // This element was already there
                        assert(pre.shared_pending_in_range());
                        assert(pre.shared_pending.count(x) > 0);
                    }
                }
            }
        }

        #[inductive(shared_finish)]
        fn shared_finish_inductive(pre: Self, post: Self, r: int) {
            // Precondition: !exc_locked, shared_pending.count(r) > 0
            // Transition: shared_pending = shared_pending - {r}, shared_guard = shared_guard + {(r, t)}
            // where t = pre.storage->0

            // Assume all pre invariants hold
            assume(pre.ref_counts_domain());
            assume(pre.exc_inv());
            assume(pre.shared_pending_in_range());
            assume(pre.shared_guard_in_range());
            assume(pre.shared_inv_agree());
            assume(pre.shared_counts_agree());

            let t = pre.storage->0; // The value stored

            // Most invariants preserved
            assert(post.ref_counts_domain());
            assert(post.exc_inv());
            assert(post.shared_pending_in_range());
            assert(post.shared_counts_agree());

            // Prove shared_guard_in_range
            assert(post.shared_guard_in_range()) by {
                assert forall |x| post.shared_guard.count(x) > 0 implies (0 <= x.0 < post.rc_width) by {
                    if x == (r, t) {
                        // This is the new element
                        assert(0 <= r < post.rc_width) by {
                            assert(pre.shared_pending_in_range());
                            assert(pre.shared_pending.count(r) > 0);
                        }
                    } else {
                        // Existing element
                        assert(pre.shared_guard_in_range());
                        assert(pre.shared_guard.count(x) > 0);
                    }
                }
            }

            // Prove shared_inv_agree
            assert(post.shared_inv_agree()) by {
                assert forall |v| #[trigger] post.shared_guard.count(v) > 0 implies
                    post.storage == Option::Some(v.1) by {

                    if v == (r, t) {
                        // This is the new element we added
                        assert(post.storage == Option::Some(t));
                        assert(v.1 == t);
                    } else {
                        // Existing element
                        assert(pre.shared_inv_agree());
                        assert(pre.shared_guard.count(v) > 0);
                        assert(pre.storage == post.storage);
                    }
                }
            }
        }

        #[inductive(shared_release)]
        fn shared_release_inductive(pre: Self, post: Self, val: (int, T)) {
            let r = val.0;

            // Precondition: shared_guard.count(val) > 0, which means ref_counts[r] > 0
            // Transition: shared_guard = shared_guard - {val}, ref_counts[r] = ref_counts[r] - 1

            // Assume all pre invariants hold
            assume(pre.ref_counts_domain());
            assume(pre.exc_inv());
            assume(pre.shared_pending_in_range());
            assume(pre.shared_guard_in_range());
            assume(pre.shared_inv_agree());
            assume(pre.shared_counts_agree());

            // Most invariants preserved
            assert(post.ref_counts_domain());
            assert(post.exc_inv());
            assert(post.shared_pending_in_range());
            assert(post.shared_guard_in_range());

            // Prove shared_inv_agree
            assert(post.shared_inv_agree()) by {
                assert forall |v| #[trigger] post.shared_guard.count(v) > 0 implies
                    post.storage == Option::Some(v.1) by {
                    assert(pre.shared_inv_agree());
                    // Elements only removed, so property preserved
                }
            }

            // Prove shared_counts_agree
            assert(post.shared_counts_agree()) by {
                assert forall |i| 0 <= i < post.rc_width implies
                    #[trigger] post.ref_counts.index(i) ==
                        post.shared_pending.count(i) as int +
                            Self::filter_r(post.shared_guard, i).len() as int by {

                    assert(post.shared_pending == pre.shared_pending);

                    if i == r {
                        // This is the element we modified
                        // We removed one element from shared_guard with first component r
                        // So Self::filter_r(shared_guard, r) should have one less element
                        assert(Self::filter_r(post.shared_guard, r).len() == Self::filter_r(pre.shared_guard, r).len() - 1) by {
                            assert(Self::filter_r(pre.shared_guard, r).count(val) > 0);
                            assert(Self::filter_r(post.shared_guard, r) == Self::filter_r(pre.shared_guard, r).remove(val));
                        };
                        assert(post.ref_counts.index(r) == pre.ref_counts.index(r) - 1);

                        // We need to show:
                        // pre.ref_counts.index(r) - 1 ==
                        //   pre.shared_pending.count(r) + (Self::filter_r(pre.shared_guard, r).len() - 1)
                        // Simplifying:
                        // pre.ref_counts.index(r) == pre.shared_pending.count(r) + Self::filter_r(pre.shared_guard, r).len()
                        // Which is our inductive hypothesis
                        assert(pre.shared_counts_agree());
                        assert(pre.shared_counts_agree() ==> (0 <= r < pre.rc_width ==> #[trigger] pre.ref_counts.index(r) ==
                            pre.shared_pending.count(r) as int + Self::filter_r(pre.shared_guard, r).len() as int));
                    } else {
                        // Unchanged
                        assert(post.ref_counts.index(i) == pre.ref_counts.index(i));
                        assert(Self::filter_r(post.shared_guard, i) == Self::filter_r(pre.shared_guard, i));
                    }
                }
            }
        }
    }
}

